    @Test
    void revokeMakesStructuredOperationsGone() throws Exception {
        grant("g-1", "subj-a", "RESEARCH").andExpect(status().isOk());
        writeStructured("w-1", "subj-a", "RESEARCH", "rec-1", "{\"x\":\"a\"}").andExpect(status().isOk());
