                .andExpect(status().isGone())
                .andExpect(jsonPath("$.code").value("CONSENT_REVOKED"));
        // 撤回后重放原写入请求（同 requestId 同参数）也必须被拒绝
        writeStructured("w-1", "subj-a", "RESEARCH", "rec-1", "{\"x\":\"a\"}")
                .andExpect(status().isGone())
                .andExpect(jsonPath("$.code").value("CONSENT_REVOKED"));
